#define pi acos(-1.)
#define sq sqrt(3.) / 3.

void grid(vec2 u, out vec2 p) {
    float v;
    vec2 q, m;

    q = u - vec2(0, -sq);
    p.y = dot(q, q); 

    m = u - vec2(-1, sq) / 2.;
    v = dot(m, m); if(v < p.y) {p.y = v; q = m;}

    m = u - vec2(1, sq) / 2.;
    v = dot(m, m); if(v < p.y) {p.y = v; q = m;}

    p = q;
}

void hex(vec2 u, out vec2 p, out bool checker){
    vec2 q, id, A, B;

    q = u;

    vec2 H = vec2(1, 2. * sq);

    q.x += fract(q.y * sq) > .5 ? .0 : .5;
    q    = (mod(q * H, 1.) - .5) / H;

    id = u - q;
    float d = sin(dot(id, vec2(1))) + id.x * .1;

    grid(q, A);
    grid(q * vec2(1, -1), B);

    checker = fract(d) > .5;

    p = A;
    if(checker) p = B;
}

void mainImage(out vec4 o, vec2 u) {
    vec4 c = vec4(2, 3, 4, 0) / 7.; 
    vec2 r = iResolution.xy, q;
    u = 2. * (u + u - r) / r.y + iTime * .5;

    vec2 p;
    bool checker;
    hex(u, p, checker);

    p = vec2(
            atan(p.y, p.x) / pi * 6., 
            length(p) - .288
        );

    o  = vec4(1);
    o -= abs(p.y) * 50. - 3.;
    o *= tanh(cos((p.x + iTime * 2.) * pi) * 5.) * .35 + .5;
    o  = max(o, checker? c : c.zyxw);
}
